import statistics
def selection_gain(perf_top, perf_rand_list):
    return perf_top - statistics.mean(perf_rand_list)

import itertools
def ranking_acc(p_hat, p):
    ok=tot=0
    for a,b in itertools.combinations(range(len(p)),2):
        ok += ((p_hat[a]-p_hat[b])*(p[a]-p[b])>0); tot+=1
    return ok/tot
